import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
void main()=>runApp(const CodageApp());
const mint=Color(0xff65e3b4),bg=Color(0xff101322),panel=Color(0xff1b2033);
class CodageApp extends StatelessWidget{const CodageApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'CODAGE',debugShowCheckedModeBanner:false,theme:ThemeData(brightness:Brightness.dark,scaffoldBackgroundColor:bg,colorScheme:ColorScheme.fromSeed(seedColor:mint,brightness:Brightness.dark),useMaterial3:true),home:const Home());}
class Lesson{final String title,desc,code,question;final List<String> choices;final int answer;const Lesson(this.title,this.desc,this.code,this.question,this.choices,this.answer);}
class Course{final String name,desc,tag;final Color color;final List<Lesson> lessons;const Course(this.name,this.desc,this.tag,this.color,this.lessons);}
const courses=[
Course('HTML','Structure des pages web','WEB',Color(0xffffa36d),[
Lesson('Balises','HTML structure une page à l’aide de balises pour les titres, paragraphes, liens et contenus.','<h1>Mon site</h1>\n<p>Bienvenue !</p>','Quelle balise crée un titre principal ?',['<h1>','<p>','<img>'],0),
Lesson('Structure HTML','DOCTYPE, html, head et body forment la structure habituelle d’une page.','<!DOCTYPE html>\n<html>\n<head><title>Ma page</title></head>\n<body><h1>Salut</h1></body>\n</html>','Quel bloc contient le contenu visible ?',['<head>','<body>','<title>'],1),
Lesson('Liens et images','La balise a crée un lien. img affiche une image et alt donne une description.','<a href="https://example.com">Lien</a>\n<img src="photo.png" alt="Description">','Quelle balise crée un lien ?',['<a>','<href>','<link>'],0)]),
Course('CSS','Styles et mise en page','CSS',Color(0xff72b7ff),[
Lesson('Premiers styles','CSS règle les couleurs, tailles, espacements et positionnement.','h1 {\n color: royalblue;\n font-size: 32px;\n}','CSS sert à…',['Structurer','Styliser une page','Compiler'],1),
Lesson('Classes','Les classes réutilisent des styles. On les cible avec un point en CSS.','.carte {\n padding: 16px;\n background: #20263a;\n}','Quel symbole cible une classe ?',['#','.','*'],1),
Lesson('Flexbox','Flexbox organise les éléments. display:flex active le mode, gap règle les espaces.','.ligne {\n display: flex;\n gap: 12px;\n justify-content: center;\n}','Comment activer Flexbox ?',['display:flex','position:flex','flex:display'],0)]),
Course('JavaScript','Interactions et logique web','JS',Color(0xfff3d66c),[
Lesson('Variables','const garde une valeur qui ne sera pas réassignée. let sert si elle peut changer.','const nom = "Sam";\nlet score = 0;\nscore++;\nconsole.log(score);','Quelle variable peut être modifiée ?',['const','let','static'],1),
Lesson('Conditions','if vérifie une condition, else traite le cas contraire.','if (score >= 10) {\n console.log("Bravo");\n} else {\n console.log("Continue");\n}','Quel mot commence un test ?',['if','for','var'],0),
Lesson('Fonctions','Les fonctions regroupent du code réutilisable. return renvoie une valeur.','function addition(a, b) {\n return a + b;\n}\naddition(3, 4);','addition(3, 4) renvoie…',['34','7','undefined'],1)]),
Course('Python','Programmation et automatisation','PY',Color(0xff9d91ff),[
Lesson('Afficher du texte','Python est polyvalent. print() affiche des informations.','print("Bonjour CODAGE !")\nnom = "Sam"\nprint("Bienvenue", nom)','Quelle fonction affiche du texte ?',['echo()','print()','write()'],1),
Lesson('Types','int : entier, float : décimal, str : texte, bool : vrai/faux.','age = 17\nprix = 2.5\nnom = "Sam"\nactif = True','Quel type représente du texte ?',['int','bool','str'],2),
Lesson('Boucles','for parcourt une séquence. range(5) produit cinq valeurs de 0 à 4.','for i in range(5):\n    print("Tour", i)','range(5) produit combien de valeurs ?',['4','5','6'],1)]),
Course('Dart & Flutter','Langage et interface mobile','APP',Color(0xff7ad6e9),[
Lesson('Dart','Dart est le langage utilisé par Flutter. On peut préciser les types ou laisser Dart les déduire.','String nom = "CODAGE";\nint xp = 0;\nfinal version = "1.0";','Flutter utilise quel langage ?',['Dart','Ruby','HTML'],0),
Lesson('Fonctions','Les fonctions prennent des paramètres et peuvent renvoyer une valeur. => est une forme concise.','int add(int a, int b) {\n return a + b;\n}\nint doubleN(int n) => n * 2;','add(2,3) retourne…',['23','5','2'],1),
Lesson('Widgets','Flutter compose les interfaces avec des widgets comme Scaffold, AppBar et Text.','Scaffold(\n appBar: AppBar(title: Text("CODAGE")),\n body: Center(child: Text("Salut")),\n)','Flutter utilise pour l’interface…',['Widgets','HTML uniquement','Excel'],0)])];

class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{int tab=0,xp=0;Set<String> done={};@override void initState(){super.initState();_load();}
Future<void> _load()async{final p=await SharedPreferences.getInstance();if(!mounted)return;setState(()=>done=p.getStringList('done')?.toSet()??{});xp=p.getInt('xp')??done.length*25;}
Future<void> mark(String id)async{if(done.contains(id))return;setState(()=>done.add(id));xp+=25;final p=await SharedPreferences.getInstance();await p.setStringList('done',done.toList());await p.setInt('xp',xp);}
int get total=>courses.fold<int>(0,(n,c)=>n+c.lessons.length);
@override Widget build(BuildContext c){final pages=[homePage(),catalog(),progress()];return Scaffold(body:SafeArea(child:pages[tab]),bottomNavigationBar:NavigationBar(backgroundColor:panel,selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const [NavigationDestination(icon:Icon(Icons.home_outlined),label:'Accueil'),NavigationDestination(icon:Icon(Icons.code),label:'Cours'),NavigationDestination(icon:Icon(Icons.trending_up),label:'Progrès')]));}
Widget homePage()=>ListView(padding:const EdgeInsets.all(20),children:[const SizedBox(height:10),Row(children:[Container(width:48,height:48,decoration:BoxDecoration(color:mint.withOpacity(.15),borderRadius:BorderRadius.circular(14)),child:const Icon(Icons.terminal,color:mint)),const SizedBox(width:12),const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('CODAGE',style:TextStyle(fontSize:24,fontWeight:FontWeight.w900,letterSpacing:2)),Text('Apprends à programmer',style:TextStyle(color:Colors.white60))])]),const SizedBox(height:24),Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xff263a50),Color(0xff172432)]),borderRadius:BorderRadius.circular(22)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('TA PROGRESSION',style:TextStyle(color:mint)),Text(xp.toString()+' XP',style:const TextStyle(fontSize:32,fontWeight:FontWeight.bold)),Text(done.length.toString()+' leçons validées sur '+total.toString()),LinearProgressIndicator(value:done.length/total,color:mint,backgroundColor:Colors.white12),Text((done.length/total*100).round().toString()+'% accompli')])),const SizedBox(height:24),const Text('Commencer à apprendre',style:TextStyle(fontSize:21,fontWeight:FontWeight.bold)),const SizedBox(height:12),...courses.map(courseCard),const Text('Autres langages à venir',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold)),note('Java, Kotlin, C, C++, C#, SQL et autres parcours seront ajoutés progressivement.')]);
Widget catalog()=>ListView(padding:const EdgeInsets.all(20),children:[const SizedBox(height:10),const Text('Catalogue',style:TextStyle(fontSize:26,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Choisis un langage pour commencer.'),const SizedBox(height:18),...courses.map(courseCard)]);
Widget progress()=>ListView(padding:const EdgeInsets.all(20),children:[const SizedBox(height:10),const Text('Ma progression',style:TextStyle(fontSize:26,fontWeight:FontWeight.bold)),Container(padding:const EdgeInsets.all(18),margin:const EdgeInsets.only(top:16),decoration:BoxDecoration(color:panel,borderRadius:BorderRadius.circular(16)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Niveau',style:TextStyle(color:Colors.white60)),Text((1+xp~/100).toString(),style:const TextStyle(fontSize:30,color:mint)),Text(xp.toString()+' XP'),LinearProgressIndicator(value:(xp%100)/100,color:mint),Text((xp%100).toString()+'/100 XP pour le prochain niveau')])),const SizedBox(height:18),...courses.map((c){final n=c.lessons.where((l)=>done.contains(c.name+':'+l.title)).length;return Container(margin:const EdgeInsets.only(top:12),padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:panel,borderRadius:BorderRadius.circular(16)),child:Column(children:[Row(children:[CircleAvatar(child:Text(c.tag)),Expanded(child:Text(c.name)),Text(n.toString()+'/'+c.lessons.length.toString())]),LinearProgressIndicator(value:n/c.lessons.length,color:c.color)]));})]);
Widget courseCard(Course c){final n=c.lessons.where((l)=>done.contains(c.name+':'+l.title)).length;return InkWell(onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>CoursePage(course:c,done:done,onMark:mark))),child:Container(margin:const EdgeInsets.only(bottom:12),padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:panel,borderRadius:BorderRadius.circular(18),border:Border.all(color:c.color.withOpacity(.2))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[CircleAvatar(backgroundColor:c.color.withOpacity(.15),child:Text(c.tag,style:TextStyle(color:c.color))),const SizedBox(width:12),Expanded(child:Text(c.name,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:17))),const Icon(Icons.chevron_right)]),Text(c.desc,style:const TextStyle(color:Colors.white60)),LinearProgressIndicator(value:n/c.lessons.length,color:c.color,backgroundColor:Colors.white12)])));}
Widget note(String s)=>Container(margin:const EdgeInsets.only(top:8),padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:panel,borderRadius:BorderRadius.circular(16)),child:Text(s,style:const TextStyle(color:Colors.white60)));
}
class CoursePage extends StatelessWidget{final Course course;final Set<String> done;final Future<void> Function(String) onMark;const CoursePage({super.key,required this.course,required this.done,required this.onMark});
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(course.name)),body:ListView(padding:const EdgeInsets.all(16),children:[Text(course.desc,style:const TextStyle(fontSize:20)),const SizedBox(height:14),...course.lessons.asMap().entries.map((e){final l=e.value,id=course.name+':'+e.value.title,finished=done.contains(id);return Card(color:panel,child:ListTile(leading:Icon(finished?Icons.check_circle:Icons.play_circle,color:course.color),title:Text(l.title),subtitle:Text(l.desc,maxLines:2),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>LessonPage(course:course,lesson:l,number:e.key+1,finished:finished,onMark:()=>onMark(id)))));})]));}
}
class LessonPage extends StatefulWidget{final Course course;final Lesson lesson;final int number;final bool finished;final Future<void> Function() onMark;const LessonPage({super.key,required this.course,required this.lesson,required this.number,required this.finished,required this.onMark});@override State<LessonPage> createState()=>_LessonPageState();}
class _LessonPageState extends State<LessonPage>{int? choice;bool checked=false;@override Widget build(BuildContext c){final l=widget.lesson;return Scaffold(appBar:AppBar(title:Text('Leçon '+widget.number.toString())),body:ListView(padding:const EdgeInsets.all(16),children:[Text(widget.course.name.toUpperCase(),style:TextStyle(color:widget.course.color)),Text(l.title,style:const TextStyle(fontSize:26,fontWeight:FontWeight.bold)),const SizedBox(height:12),Text(l.desc,style:const TextStyle(fontSize:16,height:1.5)),Container(margin:const EdgeInsets.symmetric(vertical:16),padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:const Color(0xff090c15),borderRadius:BorderRadius.circular(12)),child:SelectableText(l.code,style:const TextStyle(fontFamily:'monospace',color:Color(0xffb7d9ff),height:1.5))),const Text('Quiz rapide',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),Text(l.question),const SizedBox(height:10),...l.choices.asMap().entries.map((e)=>Padding(padding:const EdgeInsets.only(bottom:6),child:OutlinedButton(onPressed:checked?null:()=>setState(()=>choice=e.key),style:OutlinedButton.styleFrom(alignment:Alignment.centerLeft,backgroundColor:choice==e.key?Colors.white10:null),child:Text(e.value)))),if(checked)Text(choice==l.answer?'Bravo, bonne réponse !':'Pas tout à fait, relis la leçon.',style:TextStyle(color:choice==l.answer?mint:Colors.orangeAccent)),FilledButton(onPressed:choice==null||checked?null:()=>setState(()=>checked=true),child:const Text('Vérifier')),const SizedBox(height:8),FilledButton.icon(onPressed:widget.finished?null:()async{await widget.onMark();if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Leçon terminée : +25 XP !')));},icon:const Icon(Icons.check),label:Text(widget.finished?'Déjà validée':'Terminer (+25 XP)'))]));}}
